Bash(python3 << 'EOF'
import zipfile
import xml.etree.ElementTree as ET

with zipfile.ZipFile\("QFusion安装前后检查项.docx"\) as z:
    xml_content = z.read\("word/document.xml"\)
    root = ET.fromstring\(xml_content\)

    # 提取所有文本
    text_elements = []
    for elem in root.iter\(\):
        if elem.text and elem.text.strip\(\):
            text_elements.append\(elem.text.strip\(\)\)

    # 找到安装前检查项部分
    in_install_before = False
    results = []
    current_item = {}

    for i, text in enumerate\(text_elements\):
        if '安装前' in text:
            in_install_before = True
            if current_item:
                results.append\(current_item\)
            current_item = {'序号': text.split\('安装前'\)[0], '内容': text}
        elif in_install_before and \('安装后' in text or i == len\(text_elements\) - 1\):
            in_install_before = False
            if current_item:
                results.append\(current_item\)
                current_item = {}
        elif in_install_before and text.strip\(\):
            if '详情' not in current_item:
                current_item['详情'] = []
            current_item['详情'].append\(text\)

    # 打印结果
    print\("安装前检查项:"\)
    print\("=" * 80\)
    for item in results[:15]:  # 显示前15个
        print\(f"\\n序号: {item.get\('序号', 'N/A'\)}"\)
        print\(f"内容: {item.get\('内容', 'N/A'\)}"\)
        if '详情' in item:
            print\(f"详情: {' '.join\(item['详情'][:5]\)}"\)
EOF)
